 Options(false,false,true,false);yield return Refresh();string off=Note();Options(false,true,true,false);yield return Refresh();Check(Note()!=off,"navigation help independent of symbols");yield return Shot("office-on");Options(false,false,false,false);yield return Refresh();yield return Shot("office-off");
 m.ShowPause();a.ShowSettings();a.OpenCategory("Cognitiva");yield return Refresh();string normal=UI();((ScrollRect)Get(a,"scroll")).verticalNormalizedPosition=0;yield return Settle();yield return Shot("preview-off");P.simpleLanguage=true;yield return Refresh();string simple=UI();Check(normal!=simple&&simple.Contains("Abra el expediente"),"preview reflects simple instructions");P.symbols=true;yield return Refresh();((ScrollRect)Get(a,"scroll")).verticalNormalizedPosition=0;yield return Settle();yield return Shot("preview-on");Check(State()==campaign,"preview leaves campaign unchanged");
 yield return Activate("Glosario político");Check(a.CustomPage=="Glosario","consult glossary with contextual glossary OFF");string glossaryText=UI();Check(glossaryText.Contains("Estabilidad:")&&glossaryText.Contains("Prosperidad:")&&glossaryText.Contains("Alianza:"),"glossary defines indicators and alliance");yield return Keypress(Key.Escape);Check(a.CustomPage=="Cognitiva","glossary returns to originating category");
 if(before){log.Add("COMPLETE baseline, failures record reproduced defects");File.WriteAllLines(dir+"/results.txt",log);EditorApplication.Exit(0);yield break;}
 foreach(string title in new[]{"Instrucciones sencillas","Ayudas de navegación","Símbolos explicativos","Glosario disponible"}){a.OpenCategory("Cognitiva");yield return Refresh();yield return Seek(title);string prev=Focused.text;yield return Keypress(Key.Enter);yield return Seek(title);Check(Focused.text!=prev,"real UI switch changes state: "+title);yield return Keypress(Key.Space);yield return Seek(title);Check(Focused.text==prev,"Space reverses switch: "+title);}
 a.ClosePanels();m.Resume();yield return Refresh();campaign=State();for(int bits=0;bits<16;bits++){Options((bits&1)!=0,(bits&2)!=0,(bits&4)!=0,(bits&8)!=0);yield return Refresh();Check(P.simpleLanguage==((bits&1)!=0)&&P.navigationHelp==((bits&2)!=0)&&P.symbols==((bits&4)!=0)&&P.glossary==((bits&8)!=0),"independent combination "+bits);Check(State()==campaign,"combination preserves campaign "+bits);var button=g.GetComponentsInChildren<Button>(true).First(b=>b.name=="GuidedGlossary");Check(button.gameObject.activeSelf==P.glossary,"context glossary visibility "+bits);Check(g.AccessIndicators().Contains("[=]")==P.symbols,"indicator symbols follow preference "+bits);}
