 Options(true,true,true,true);P.simpleDocuments=true;yield return Refresh();yield return Seek("Seleccionar expediente");yield return Keypress(Key.Enter);Check(Note().Contains("zona de lectura"),"selected document hint identifies target");yield return Seek("Colocar expediente");yield return Keypress(Key.Space);Check(D.CanDecide&&Note().Contains("sello"),"opened document explains decision");Check(a.Snapshot().Where(e=>e.text.Contains("Seleccionar sello")).All(e=>e.text.StartsWith("[>]")),"stamp selection uses action symbol not security");var stamp=g.GetComponentsInChildren<StampTool>().First(x=>x.AccessAvailable);a.SelectStamp(stamp);yield return Refresh();Check(a.Snapshot().Any(e=>e.text.StartsWith("[>] Aplicar sello")),"stamp confirmation uses action symbol not visited");Check(Note().Contains("confirmar"),"stamp hint explains confirmation");yield return Activate("Aplicar sello");Check(g.TutorialAnswered&&Note().Contains("CONTINUAR"),"result hint explains continuation");yield return Shot("result-help");Call("ArchiveCard");yield return Settle();Call("ShowMap");yield return Refresh();string mapText=string.Join("\n",g.GetComponentsInChildren<Text>().Select(t=>t.text));Check(mapText.Contains("sospechas"),"map guidance preserves uncertainty");yield return Shot("map-help");var country=g.GetComponentsInChildren<AccessMapCountry>().First(x=>x.Label.Contains("Disponible"));country.Activate();yield return Refresh();var hint=g.GetComponentInChildren<GameplayGuidanceNote>();Check(hint!=null&&hint.GetComponent<Text>().text.Contains("INTELIGENCIA"),"diplomacy help explains reports");string narrative=string.Join("\n",g.GetComponentsInChildren<Text>().Where(t=>t.text.Contains("«")).Select(t=>t.text));string visit=State();yield return Shot("visit-on");P.navigationHelp=false;yield return Refresh();Check(!hint.GetComponent<Text>().text.Contains("HERRAMIENTAS"),"OFF removes extra diplomatic hint");Check(State()==visit,"diplomatic help changes no campaign state");yield return Shot("visit-off");P.simpleLanguage=false;yield return Refresh();Check(string.Join("\n",g.GetComponentsInChildren<Text>().Where(t=>t.text.Contains("«")).Select(t=>t.text))==narrative,"narrative untouched by simple language");
 m.ShowPause();a.ShowSettings();a.OpenCategory("Cognitiva");yield return Refresh();yield return Activate("Tutorial y ayudas contextuales");Check(m.PageName=="Consulta","tutorial button opens manual");var steps=(TutorialStepData[])typeof(DeskMenus).GetProperty("ManualSteps",F).GetValue(m);Check(steps.Length==18&&TutorialLessons.Titles.Length==12,"12 lessons and 18 notes");campaign=State();P.simpleDocuments=false;Options(false,false,false,false);m.ShowLesson(0);yield return Refresh();for(int n=0;n<18;n++){var body=m.GetComponentsInChildren<Text>().First(t=>t.name=="TutorialBody");Check(body.text==TutorialLessons.Text(steps[n],g.TutorialQuestions),"complete normal manual note "+n);if(n<17){yield return Seek("SIGUIENTE");yield return Keypress(n%2==0?Key.Enter:Key.Space);}}
 for(int lesson=0;lesson<12;lesson++){P.simpleLanguage=false;m.ShowLesson(lesson);yield return Refresh();string original=m.GetComponentsInChildren<Text>().First(t=>t.name=="TutorialBody").text;P.simpleLanguage=true;m.ShowLesson(lesson);yield return Refresh();Check(m.GetComponentsInChildren<Text>().First(t=>t.name=="TutorialBody").text!=original,"simple manual lesson "+lesson);}
 yield return Activate("ATRÁS");yield return Keypress(Key.RightArrow);Check(VisibleFocus(),"tutorial arrows retain visible focus");yield return Keypress(Key.Escape);Check(m.PageName=="Cómo jugar","ESC returns to twelve lesson index");Check(State()==campaign,"consulting all notes preserves tutorial and campaign");
 a.ShowSettings();a.OpenCategory("Cognitiva");P.textScale=1.75f;DeskPreferences.Current.highContrast=true;Options(true,true,true,true);yield return Refresh();((ScrollRect)Get(a,"scroll")).verticalNormalizedPosition=0;yield return Settle();yield return Shot("preview-175-contrast");yield return Activate("Glosario político");yield return Refresh();var sc=(ScrollRect)Get(a,"scroll");Check(sc.content.rect.height>sc.viewport.rect.height,"175 percent glossary scrolls");yield return Keypress(Key.PageDown);Check(sc.verticalNormalizedPosition<1,"keyboard scroll moves glossary");yield return Shot("glossary-175");yield return Keypress(Key.Escape);Check(a.CustomPage=="Cognitiva","enlarged glossary returns correctly");P.Save();DeskPreferences.Current.Save();File.WriteAllText("Logs/Comprehension-dir.txt",DeskPreferences.TestDirectory);File.WriteAllText("Logs/Comprehension-expected.txt",JsonUtility.ToJson(P));log.Add("COMPLETE simulated Keyboard/Mouse and callbacks in Unity Play Mode; human comprehension not tested");File.WriteAllLines(dir+"/results.txt",log);EditorApplication.Exit(log.Any(x=>x.StartsWith("FAIL"))?1:0);
