public static class ComprehensionRunner {
 public static void Live(){SessionState.SetBool("ComprehensionLive",true);Run();}
 public static void Before(){SessionState.SetBool("ComprehensionBefore",true);Run();}
 public static void Run(){SessionState.SetBool("ComprehensionRun",true);SessionState.SetString("ComprehensionDir",Path.Combine(Path.GetTempPath(),"DespachoComprehension-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 public static void Restart(){DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=File.ReadAllText("Logs/Comprehension-dir.txt");DeskPreferences.Load();AccessPreferences.Load();bool ok=JsonUtility.ToJson(AccessPreferences.Current)==File.ReadAllText("Logs/Comprehension-expected.txt");File.WriteAllText("Logs/Comprehension-restart.txt",ok?"PASS full preferences preserved after new process":"FAIL preferences");EditorApplication.Exit(ok?0:1);}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void BeforeScene(){if(SessionState.GetBool("ComprehensionRun",false))DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=SessionState.GetString("ComprehensionDir","");}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("ComprehensionRun",false))return;SessionState.SetBool("ComprehensionRun",false);new GameObject("ComprehensionProbe").AddComponent<ComprehensionProbe>();}
